class Solution:
    def jump(self, nums: List[int]) -> int:
        minStep = [float('inf')] * len(nums)
        minStep[-1] = 0
        for i in range(len(nums) - 2, -1, -1):
            # 对于某个下标i, 遍历它可达的所有下标, 选取其中跳跃到最后下标的最小值.
            for j in range(i + 1, min(len(nums), i + nums[i] + 1)):
                minStep[i] = min(minStep[i], minStep[j] + 1)
        return minStep[0]
